80	std::unique_ptr<Command> FtpInitiateConnectionCommand::createNextCommandProxied(
81	    const std::string& hostname, const std::string& addr, uint16_t port,
82	    const std::vector<std::string>& resolvedAddresses,
83	    const std::shared_ptr<Request>& proxyRequest)
84	{
85	  std::string options;
86	  std::shared_ptr<SocketCore> pooledSocket;
87	  std::string proxyMethod = resolveProxyMethod(getRequest()->getProtocol());
88	
89	  // sftp always use tunnel mode
90	  if (proxyMethod == V_GET) {
91	    pooledSocket = getDownloadEngine()->popPooledSocket(
92	        getRequest()->getHost(), getRequest()->getPort(),
93	        proxyRequest->getHost(), proxyRequest->getPort());
94	  }
95	  else {
96	    pooledSocket = getDownloadEngine()->popPooledSocket(
97	        options, getRequest()->getHost(), getRequest()->getPort(),
98	        getDownloadEngine()
99	            ->getAuthConfigFactory()
100	            ->createAuthConfig(getRequest(), getOption().get())
101	            ->getUser(),
102	        proxyRequest->getHost(), proxyRequest->getPort());
103	  }
104	
105	  if (!pooledSocket) {
106	    A2_LOG_INFO(fmt(MSG_CONNECTING_TO_SERVER, getCuid(), addr.c_str(), port));
107	    createSocket();
108	    getSocket()->establishConnection(addr, port);
109	
110	    getRequest()->setConnectedAddrInfo(hostname, addr, port);
111	
112	    auto c = make_unique<ConnectCommand>(getCuid(), getRequest(), proxyRequest,
113	                                         getFileEntry(), getRequestGroup(),
114	                                         getDownloadEngine(), getSocket());
115	    if (proxyMethod == V_GET) {
116	      // Use GET for FTP via HTTP proxy.
117	      getRequest()->setMethod(Request::METHOD_GET);
118	      c->setControlChain(std::make_shared<HttpRequestConnectChain>());
119	    }
120	    else if (proxyMethod == V_TUNNEL) {
121	      c->setControlChain(std::make_shared<FtpTunnelRequestConnectChain>());
122	    }
123	    else {
124	      // Unreachable
125	      assert(0);
126	      return nullptr;
127	    }
128	    setupBackupConnection(hostname, addr, port, c.get());
129	    return std::move(c);
130	  }
131	
132	  setConnectedAddrInfo(getRequest(), hostname, pooledSocket);
133	  if (proxyMethod == V_TUNNEL) {
134	#ifdef HAVE_LIBSSH2
135	    if (getRequest()->getProtocol() == "sftp") {
136	      return make_unique<SftpNegotiationCommand>(
137	          getCuid(), getRequest(), getFileEntry(), getRequestGroup(),
138	          getDownloadEngine(), pooledSocket,
139	          SftpNegotiationCommand::SEQ_SFTP_OPEN);
140	    }
141	#endif // HAVE_LIBSSH2
142	
143	    // options contains "baseWorkingDir"
144	    return make_unique<FtpNegotiationCommand>(
145	        getCuid(), getRequest(), getFileEntry(), getRequestGroup(),
146	        getDownloadEngine(), pooledSocket,
147	        FtpNegotiationCommand::SEQ_SEND_CWD_PREP, options);
148	  }
149	
150	  assert(getRequest()->getProtocol() == "ftp");
151	
152	  if (proxyMethod != V_GET) {
153	    assert(0);
154	    return nullptr;
155	  }
156	
157	  // Use GET for FTP via HTTP proxy.
158	  getRequest()->setMethod(Request::METHOD_GET);
159	  auto socketRecvBuffer = std::make_shared<SocketRecvBuffer>(pooledSocket);
160	  auto hc = std::make_shared<HttpConnection>(getCuid(), pooledSocket,
161	                                             socketRecvBuffer);
162	
163	  auto c = make_unique<HttpRequestCommand>(
164	      getCuid(), getRequest(), getFileEntry(), getRequestGroup(), hc,
165	      getDownloadEngine(), pooledSocket);
166	  c->setProxyRequest(proxyRequest);
167	  return std::move(c);
