176	      getDownloadEngine()->popPooledSocket(
177	          options, resolvedAddresses, getRequest()->getPort(),
178	          getDownloadEngine()
179	              ->getAuthConfigFactory()
180	              ->createAuthConfig(getRequest(), getOption().get())
181	              ->getUser());
182	
183	  if (!pooledSocket) {
184	    A2_LOG_INFO(fmt(MSG_CONNECTING_TO_SERVER, getCuid(), addr.c_str(), port));
185	    createSocket();
186	    getSocket()->establishConnection(addr, port);
187	    getRequest()->setConnectedAddrInfo(hostname, addr, port);
188	    auto c = make_unique<ConnectCommand>(getCuid(), getRequest(), nullptr,
189	                                         getFileEntry(), getRequestGroup(),
190	                                         getDownloadEngine(), getSocket());
191	
192	    if (getRequest()->getProtocol() == "sftp") {
193	#ifdef HAVE_LIBSSH2
194	      c->setControlChain(std::make_shared<SftpNegotiationConnectChain>());
195	#else  // !HAVE_LIBSSH2
196	      assert(0);
197	#endif // !HAVE_LIBSSH2
198	    }
199	    else {
200	      c->setControlChain(std::make_shared<FtpNegotiationConnectChain>());
201	    }
202	    setupBackupConnection(hostname, addr, port, c.get());
203	    return std::move(c);
204	  }
205	
206	  setConnectedAddrInfo(getRequest(), hostname, pooledSocket);
207	
208	#ifdef HAVE_LIBSSH2
209	  if (getRequest()->getProtocol() == "sftp") {
210	    return make_unique<SftpNegotiationCommand>(
211	        getCuid(), getRequest(), getFileEntry(), getRequestGroup(),
212	        getDownloadEngine(), pooledSocket,
213	        SftpNegotiationCommand::SEQ_SFTP_OPEN);
214	  }
215	#endif // HAVE_LIBSSH2
216	
217	  // options contains "baseWorkingDir"
218	  return make_unique<FtpNegotiationCommand>(
219	      getCuid(), getRequest(), getFileEntry(), getRequestGroup(),
220	      getDownloadEngine(), pooledSocket,
221	      FtpNegotiationCommand::SEQ_SEND_CWD_PREP, options);
