224	std::unique_ptr<Command> FtpInitiateConnectionCommand::createNextCommand(
225	    const std::string& hostname, const std::string& addr, uint16_t port,
226	    const std::vector<std::string>& resolvedAddresses,
227	    const std::shared_ptr<Request>& proxyRequest)
228	{
229	  if (proxyRequest) {
