636	bool FtpNegotiationCommand::preparePasv()
637	{
638	  afterFileAllocation();
639	  if (getSocket()->getAddressFamily() == AF_INET6) {
640	    sequence_ = SEQ_SEND_EPSV;
641	  }
642	  else {
643	    sequence_ = SEQ_SEND_PASV;
644	  }
645	  return true;
646	}
