404	namespace {
405	template <typename T>
406	bool getInteger(T* dest, const char* first, const char* last)
407	{
408	  int res = 0;
409	  // We assume *dest won't overflow.
410	  for (; first != last; ++first) {
411	    if (util::isDigit(*first)) {
412	      res *= 10;
413	      res += (*first) - '0';
414	    }
415	    else {
416	      return false;
417	    }
418	  }
419	  *dest = res;
420	  return true;
421	}
422	} // namespace
