66	
67	namespace aria2 {
68	
69	SftpNegotiationCommand::SftpNegotiationCommand(
70	    cuid_t cuid, const std::shared_ptr<Request>& req,
71	    const std::shared_ptr<FileEntry>& fileEntry, RequestGroup* requestGroup,
72	    DownloadEngine* e, const std::shared_ptr<SocketCore>& socket, Seq seq)
73	    : AbstractCommand(cuid, req, fileEntry, requestGroup, e, socket),
74	      sequence_(seq),
75	      authConfig_(e->getAuthConfigFactory()->createAuthConfig(
76	          req, requestGroup->getOption().get()))
77	
78	{
79	  path_ = getPath();
80	  setWriteCheckSocket(getSocket());
81	
82	  const std::string& checksum = getOption()->get(PREF_SSH_HOST_KEY_MD);
83	  if (!checksum.empty()) {
84	    auto p = util::divide(std::begin(checksum), std::end(checksum), '=');
85	    hashType_.assign(p.first.first, p.first.second);
86	    util::lowercase(hashType_);
87	    digest_ = util::fromHex(p.second.first, p.second.second);
88	  }
89	}
90	
91	SftpNegotiationCommand::~SftpNegotiationCommand() = default;
92	
93	bool SftpNegotiationCommand::executeInternal()
94	{
95	  disableWriteCheckSocket();
96	  for (;;) {
97	    switch (sequence_) {
98	    case SEQ_HANDSHAKE:
99	      setReadCheckSocket(getSocket());
100	      if (!getSocket()->sshHandshake(hashType_, digest_)) {
101	        goto again;
102	      }
103	      A2_LOG_DEBUG(fmt("CUID#%" PRId64 " - SSH handshake success", getCuid()));
104	      sequence_ = SEQ_AUTH_PASSWORD;
105	      break;
106	    case SEQ_AUTH_PASSWORD:
107	      if (!getSocket()->sshAuthPassword(authConfig_->getUser(),
108	                                        authConfig_->getPassword())) {
109	        goto again;
110	      }
111	      A2_LOG_DEBUG(
112	          fmt("CUID#%" PRId64 " - SSH authentication success", getCuid()));
113	      sequence_ = SEQ_SFTP_OPEN;
114	      break;
115	    case SEQ_SFTP_OPEN:
116	      if (!getSocket()->sshSFTPOpen(path_)) {
117	        goto again;
118	      }
119	      A2_LOG_DEBUG(fmt("CUID#%" PRId64 " - SFTP file %s opened", getCuid(),
120	                       path_.c_str()));
121	      sequence_ = SEQ_SFTP_STAT;
122	      break;
123	    case SEQ_SFTP_STAT: {
124	      int64_t totalLength;
125	      time_t mtime;
126	      if (!getSocket()->sshSFTPStat(totalLength, mtime, path_)) {
127	        goto again;
128	      }
129	      Time t(mtime);
130	      A2_LOG_INFO(
131	          fmt("CUID#%" PRId64 " - SFTP File %s, size=%" PRId64 ", mtime=%s",
132	              getCuid(), path_.c_str(), totalLength, t.toHTTPDate().c_str()));
133	      if (!getPieceStorage()) {
134	        getRequestGroup()->updateLastModifiedTime(Time(mtime));
135	        onFileSizeDetermined(totalLength);
136	      }
137	      else {
138	        getRequestGroup()->validateTotalLength(getFileEntry()->getLength(),
139	                                               totalLength);
140	        sequence_ = SEQ_SFTP_SEEK;
141	      }
142	      break;
143	    }
144	    case SEQ_SFTP_SEEK: {
145	      sequence_ = SEQ_NEGOTIATION_COMPLETED;
146	      if (getSegments().empty()) {
147	        break;
148	      }
149	
150	      auto& segment = getSegments().front();
151	
152	      A2_LOG_INFO(fmt("CUID#%" PRId64 " - SFTP seek to %" PRId64, getCuid(),
153	                      segment->getPositionToWrite()));
154	      getSocket()->sshSFTPSeek(segment->getPositionToWrite());
155	
156	      break;
157	    }
158	    case SEQ_FILE_PREPARATION:
159	      sequence_ = SEQ_SFTP_SEEK;
160	      disableReadCheckSocket();
161	      disableWriteCheckSocket();
162	      return false;
163	    case SEQ_NEGOTIATION_COMPLETED: {
164	      auto command = make_unique<SftpDownloadCommand>(
165	          getCuid(), getRequest(), getFileEntry(), getRequestGroup(),
166	          getDownloadEngine(), getSocket(), std::move(authConfig_));
167	      command->setStartupIdleTime(
168	          std::chrono::seconds(getOption()->getAsInt(PREF_STARTUP_IDLE_TIME)));
169	      command->setLowestDownloadSpeedLimit(
170	          getOption()->getAsInt(PREF_LOWEST_SPEED_LIMIT));
171	      command->setStatus(Command::STATUS_ONESHOT_REALTIME);
172	
173	      getDownloadEngine()->setNoWait(true);
174	
175	      if (getFileEntry()->isUniqueProtocol()) {
176	        getFileEntry()->removeURIWhoseHostnameIs(getRequest()->getHost());
177	      }
178	      getRequestGroup()->getURISelector()->tuneDownloadCommand(
179	          getFileEntry()->getRemainingUris(), command.get());
180	      getDownloadEngine()->addCommand(std::move(command));
181	      return true;
182	    }
183	    case SEQ_DOWNLOAD_ALREADY_COMPLETED:
184	    case SEQ_HEAD_OK:
185	    case SEQ_EXIT:
186	      return true;
187	    };
188	  }
189	again:
190	  addCommandSelf();
191	  if (getSocket()->wantWrite()) {
192	    setWriteCheckSocket(getSocket());
193	  }
194	  return false;
195	}
196	
197	void SftpNegotiationCommand::onFileSizeDetermined(int64_t totalLength)
198	{
199	  getFileEntry()->setLength(totalLength);
200	  if (getFileEntry()->getPath().empty()) {
201	    auto suffixPath = util::createSafePath(
202	        util::percentDecode(std::begin(getRequest()->getFile()),
203	                            std::end(getRequest()->getFile())));
204	
205	    getFileEntry()->setPath(
206	        util::applyDir(getOption()->get(PREF_DIR), suffixPath));
207	    getFileEntry()->setSuffixPath(suffixPath);
208	  }
209	  getRequestGroup()->preDownloadProcessing();
210	
211	  if (totalLength == 0) {
212	    sequence_ = SEQ_NEGOTIATION_COMPLETED;
213	
214	    if (getOption()->getAsBool(PREF_DRY_RUN)) {
215	      getRequestGroup()->initPieceStorage();
216	      onDryRunFileFound();
217	      return;
218	    }
219	
220	    if (getDownloadContext()->knowsTotalLength() &&
221	        getRequestGroup()->downloadFinishedByFileLength()) {
222	      // TODO Known issue: if .aria2 file exists, it will not be
223	      // deleted on successful verification, because .aria2 file is
224	      // not loaded.  See also
225	      // HttpResponseCommand::handleOtherEncoding()
226	      getRequestGroup()->initPieceStorage();
227	      if (getDownloadContext()->isChecksumVerificationNeeded()) {
228	        A2_LOG_DEBUG("Zero length file exists. Verify checksum.");
229	        auto entry =
230	            make_unique<ChecksumCheckIntegrityEntry>(getRequestGroup());
231	        entry->initValidator();
232	        getPieceStorage()->getDiskAdaptor()->openExistingFile();
233	        getDownloadEngine()->getCheckIntegrityMan()->pushEntry(
234	            std::move(entry));
235	        sequence_ = SEQ_EXIT;
236	      }
237	      else {
238	        getPieceStorage()->markAllPiecesDone();
239	        getDownloadContext()->setChecksumVerified(true);
240	        sequence_ = SEQ_DOWNLOAD_ALREADY_COMPLETED;
241	        A2_LOG_NOTICE(fmt(MSG_DOWNLOAD_ALREADY_COMPLETED,
242	                          GroupId::toHex(getRequestGroup()->getGID()).c_str(),
243	                          getRequestGroup()->getFirstFilePath().c_str()));
244	      }
245	      poolConnection();
246	      return;
247	    }
248	
249	    getRequestGroup()->adjustFilename(std::make_shared<NullProgressInfoFile>());
250	    getRequestGroup()->initPieceStorage();
251	    getPieceStorage()->getDiskAdaptor()->initAndOpenFile();
252	
253	    if (getDownloadContext()->knowsTotalLength()) {
254	      A2_LOG_DEBUG("File length becomes zero and it means download completed.");
255	      // TODO Known issue: if .aria2 file exists, it will not be
256	      // deleted on successful verification, because .aria2 file is
257	      // not loaded.  See also
258	      // HttpResponseCommand::handleOtherEncoding()
259	      if (getDownloadContext()->isChecksumVerificationNeeded()) {
260	        A2_LOG_DEBUG("Verify checksum for zero-length file");
261	        auto entry =
262	            make_unique<ChecksumCheckIntegrityEntry>(getRequestGroup());
263	        entry->initValidator();
264	        getDownloadEngine()->getCheckIntegrityMan()->pushEntry(
265	            std::move(entry));
266	        sequence_ = SEQ_EXIT;
267	      }
268	      else {
269	        sequence_ = SEQ_DOWNLOAD_ALREADY_COMPLETED;
270	        getPieceStorage()->markAllPiecesDone();
271	      }
272	      poolConnection();
273	      return;
274	    }
275	    // We have to make sure that command that has Request object must
276	    // have segment after PieceStorage is initialized. See
277	    // AbstractCommand::execute()
278	    getSegmentMan()->getSegmentWithIndex(getCuid(), 0);
279	    return;
280	  }
281	  else {
282	    auto progressInfoFile = std::make_shared<DefaultBtProgressInfoFile>(
283	        getDownloadContext(), nullptr, getOption().get());
284	    getRequestGroup()->adjustFilename(progressInfoFile);
285	    getRequestGroup()->initPieceStorage();
286	
287	    if (getOption()->getAsBool(PREF_DRY_RUN)) {
288	      onDryRunFileFound();
289	      return;
290	    }
291	
292	    auto checkIntegrityEntry = getRequestGroup()->createCheckIntegrityEntry();
293	    if (!checkIntegrityEntry) {
294	      sequence_ = SEQ_DOWNLOAD_ALREADY_COMPLETED;
295	      poolConnection();
296	      return;
297	    }
298	    // We have to make sure that command that has Request object must
299	    // have segment after PieceStorage is initialized. See
300	    // AbstractCommand::execute()
301	    getSegmentMan()->getSegmentWithIndex(getCuid(), 0);
302	
303	    checkIntegrityEntry->pushNextCommand(std::unique_ptr<Command>(this));
304	    prepareForNextAction(std::move(checkIntegrityEntry));
305	
306	    disableReadCheckSocket();
307	
308	    sequence_ = SEQ_FILE_PREPARATION;
309	  }
310	}
311	
312	void SftpNegotiationCommand::poolConnection() const
313	{
314	  if (getOption()->getAsBool(PREF_FTP_REUSE_CONNECTION)) {
315	    // TODO we don't need options.  Probably, we need to pool socket
316	    // using scheme, port and auth info as key
317	    getDownloadEngine()->poolSocket(getRequest(), authConfig_->getUser(),
318	                                    createProxyRequest(), getSocket(), "");
319	  }
320	}
321	
322	void SftpNegotiationCommand::onDryRunFileFound()
323	{
324	  getPieceStorage()->markAllPiecesDone();
325	  getDownloadContext()->setChecksumVerified(true);
326	  poolConnection();
327	  sequence_ = SEQ_HEAD_OK;
328	}
329	
330	std::string SftpNegotiationCommand::getPath() const
331	{
332	  auto& req = getRequest();
333	  auto path = req->getDir() + req->getFile();
334	  return util::percentDecode(std::begin(path), std::end(path));
335	}
336	
337	} // namespace aria2
