57	FtpFinishDownloadCommand::FtpFinishDownloadCommand(
58	    cuid_t cuid, const std::shared_ptr<Request>& req,
59	    const std::shared_ptr<FileEntry>& fileEntry, RequestGroup* requestGroup,
60	    const std::shared_ptr<FtpConnection>& ftpConnection, DownloadEngine* e,
61	    const std::shared_ptr<SocketCore>& socket)
62	    : AbstractCommand(cuid, req, fileEntry, requestGroup, e, socket),
63	      ftpConnection_(ftpConnection)
64	{
65	}
