68	
69	// overrides AbstractCommand::execute().
70	// AbstractCommand::_segments is empty.
71	bool FtpFinishDownloadCommand::execute()
72	{
73	  if (getRequestGroup()->isHaltRequested()) {
74	    return true;
75	  }
76	  try {
77	    if (readEventEnabled() || hupEventEnabled()) {
78	      getCheckPoint() = global::wallclock();
79	      int status = ftpConnection_->receiveResponse();
80	      if (status == 0) {
81	        addCommandSelf();
82	        return false;
83	      }
84	      if (status == 226) {
85	        if (getOption()->getAsBool(PREF_FTP_REUSE_CONNECTION)) {
86	          getDownloadEngine()->poolSocket(
87	              getRequest(), ftpConnection_->getUser(), createProxyRequest(),
88	              getSocket(), ftpConnection_->getBaseWorkingDir());
89	        }
90	      }
91	      else {
92	        A2_LOG_INFO(fmt("CUID#%" PRId64 " - Bad status for transfer complete.",
93	                        getCuid()));
94	      }
95	    }
96	    else if (getCheckPoint().difference(global::wallclock()) >= getTimeout()) {
97	      A2_LOG_INFO(fmt("CUID#%" PRId64
98	                      " - Timeout before receiving transfer complete.",
99	                      getCuid()));
100	    }
101	    else {
102	      addCommandSelf();
103	      return false;
104	    }
105	  }
106	  catch (RecoverableException& e) {
107	    A2_LOG_INFO_EX(fmt("CUID#%" PRId64
108	                       " - Exception was thrown, but download was"
109	                       " finished, so we can ignore the exception.",
110	                       getCuid()),
111	                   e);
112	  }
113	  if (getRequestGroup()->downloadFinished()) {
114	    return true;
115	  }
116	  else {
117	    return prepareForRetry(0);
118	  }
119	}
120	
121	// This function never be called.
122	bool FtpFinishDownloadCommand::executeInternal() { return true; }
