292	    auto checkIntegrityEntry = getRequestGroup()->createCheckIntegrityEntry();
293	    if (!checkIntegrityEntry) {
294	      sequence_ = SEQ_DOWNLOAD_ALREADY_COMPLETED;
295	      poolConnection();
296	      return;
297	    }
298	    // We have to make sure that command that has Request object must
299	    // have segment after PieceStorage is initialized. See
300	    // AbstractCommand::execute()
301	    getSegmentMan()->getSegmentWithIndex(getCuid(), 0);
302	
303	    checkIntegrityEntry->pushNextCommand(std::unique_ptr<Command>(this));
304	    prepareForNextAction(std::move(checkIntegrityEntry));
305	
306	    disableReadCheckSocket();
307	
308	    sequence_ = SEQ_FILE_PREPARATION;
309	  }
310	}
311	
312	void SftpNegotiationCommand::poolConnection() const
313	{
314	  if (getOption()->getAsBool(PREF_FTP_REUSE_CONNECTION)) {
315	    // TODO we don't need options.  Probably, we need to pool socket
316	    // using scheme, port and auth info as key
317	    getDownloadEngine()->poolSocket(getRequest(), authConfig_->getUser(),
318	                                    createProxyRequest(), getSocket(), "");
319	  }
320	}
321	
322	void SftpNegotiationCommand::onDryRunFileFound()
323	{
324	  getPieceStorage()->markAllPiecesDone();
325	  getDownloadContext()->setChecksumVerified(true);
326	  poolConnection();
327	  sequence_ = SEQ_HEAD_OK;
328	}
329	
330	std::string SftpNegotiationCommand::getPath() const
331	{
332	  auto& req = getRequest();
333	  auto path = req->getDir() + req->getFile();
334	  return util::percentDecode(std::begin(path), std::end(path));
335	}
336	
337	} // namespace aria2
