    SEQ_NEGOTIATION_COMPLETED,
    SEQ_DOWNLOAD_ALREADY_COMPLETED,
    SEQ_HEAD_OK,
    SEQ_FILE_PREPARATION,
    SEQ_EXIT,
  };

