53	
54	SftpFinishDownloadCommand::SftpFinishDownloadCommand(
55	    cuid_t cuid, const std::shared_ptr<Request>& req,
56	    const std::shared_ptr<FileEntry>& fileEntry, RequestGroup* requestGroup,
57	    DownloadEngine* e, const std::shared_ptr<SocketCore>& socket)
58	    : AbstractCommand(cuid, req, fileEntry, requestGroup, e, socket)
59	{
60	  disableReadCheckSocket();
61	  setWriteCheckSocket(getSocket());
62	}
63	
64	SftpFinishDownloadCommand::~SftpFinishDownloadCommand() = default;
65	
66	// overrides AbstractCommand::execute().
67	// AbstractCommand::_segments is empty.
68	bool SftpFinishDownloadCommand::execute()
69	{
70	  if (getRequestGroup()->isHaltRequested()) {
71	    return true;
72	  }
73	  try {
74	    if (readEventEnabled() || writeEventEnabled() || hupEventEnabled()) {
75	      getCheckPoint() = global::wallclock();
76	
77	      if (!getSocket()->sshSFTPClose()) {
78	        setWriteCheckSocketIf(getSocket(), getSocket()->wantWrite());
79	        setReadCheckSocketIf(getSocket(), getSocket()->wantRead());
80	        addCommandSelf();
81	        return false;
82	      }
83	
84	      auto authConfig =
85	          getDownloadEngine()->getAuthConfigFactory()->createAuthConfig(
86	              getRequest(), getRequestGroup()->getOption().get());
87	
88	      getDownloadEngine()->poolSocket(getRequest(), authConfig->getUser(),
89	                                      createProxyRequest(), getSocket(), "");
90	    }
91	    else if (getCheckPoint().difference(global::wallclock()) >= getTimeout()) {
92	      A2_LOG_INFO(fmt("CUID#%" PRId64
93	                      " - Timeout before receiving transfer complete.",
94	                      getCuid()));
95	    }
96	    else {
97	      addCommandSelf();
98	      return false;
99	    }
100	  }
101	  catch (RecoverableException& e) {
102	    A2_LOG_INFO_EX(fmt("CUID#%" PRId64
103	                       " - Exception was thrown, but download was"
104	                       " finished, so we can ignore the exception.",
105	                       getCuid()),
106	                   e);
107	  }
108	  if (getRequestGroup()->downloadFinished()) {
109	    return true;
110	  }
111	  else {
112	    return prepareForRetry(0);
113	  }
114	}
